	"09001": {
		names: [{ nominative: "Forefeast of the Nativity", short: "Forefeast" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				type: "0",
				hymns: [],
				sections: [
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "And it came to pass that Mary was enrolled with Joseph the old man, in Bethlehem, since she was\nof the seed of David, and was great with the Lamb, without seed. And when the time for delivery\ndrew near, and they had no place in the village, the cave did appear to the Queen as a delightful\npalace. Verily, Christ shall be born, raising the likeness that fell of old.",
								type: "1",
								tone: "4",
								header: "Tropar of the Forefeast, Tone 4",
								author: "Unknown",
							},
							{
								kind: "kontakion",
								text: "Today the Virgin cometh to the cave where she will give birth in an ineffable manner to the Word\nWho is before all the ages. Rejoice, therefore, O universe, when thou hearest it heralded: Glorify\nHim, with the angels and the shepherds, Who chose to be seen as a new-born babe, the God Who\nis before all the ages.",
								type: "1",
								tone: "3",
								header: "Kondak of the Forefeast, Tone 3",
								author: "Unknown",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
